<template><Card class="s45-manager"><template v-if="!$route.params.id"><h2>基础对账</h2><p class="intro">固定账户、北京时间业务日、币种、覆盖范围和截至时点，分别呈现本地事实与渠道账本。本地 Mock 不替代真实账单。</p><Alert v-if="error" type="error" show-icon>{{error}}</Alert><OperationRecovery name="reconciliation:create" :revision="revision" @recovered="recovered"/><Form v-if="permissions.includes('reconciliation.create')" inline class="query"><FormItem label="渠道账户 *"><Select v-model="configId" style="width:300px" placeholder="选择本候选账户"><Option v-for="row in accounts" :key="row.configId" :value="row.configId">{{row.platformMerchant}} · {{label(row.mode)}}</Option></Select></FormItem><FormItem label="业务日期（北京） *"><DatePicker v-model="businessDate" type="date" placeholder="选择日期"/></FormItem><Button type="primary" :loading="busy" :disabled="createPending" @click="create">创建 / 重跑对账</Button></Form><RecordList endpoint="/reconciliations" :dated="false" :searchable="false" :columns="columns" :refresh-key="revision" @open="open"/></template><template v-else><Button @click="back">返回对账列表</Button><Button :loading="loading" @click="load">重新读取</Button><Alert v-if="error" type="error" show-icon>{{error}}</Alert><OperationRecovery :name="'reconciliation:review:'+selected" :revision="revision" @recovered="load"/><template v-if="detail"><h2>{{detail.businessDate}} · {{label(detail.mode)}} 对账</h2><section class="detail-section"><dl class="facts"><div v-for="row in facts" :key="row[0]" class="fact"><dt>{{row[0]}}</dt><dd>{{row[1]}}</dd></div></dl><p class="meta">覆盖本业务日创建的 Stage45 渠道请求；手续费证据未提供。完结请求和未知结果分别核对，不将差异复核当作资金修复。</p></section><section v-if="detail.coverage.internalChecks" class="detail-section"><h3>原资金与摘要内部核对</h3><p>已检查 {{detail.coverage.internalChecks.checkedOrders}} 个订单；实际差异 {{detail.coverage.internalChecks.differences}} 项，待证 {{detail.coverage.internalChecks.pending}} 项。</p><Alert v-if="detail.coverage.internalChecks.pending||!detail.coverage.providerComplete" type="warning" show-icon>本范围仍有待证或来源不完整，不能认定全部核对通过。</Alert><div class="table-scroll"><Table :columns="internalColumns" :data="detail.coverage.internalChecks.checks" no-data-text="本覆盖范围内未发现已记录的内部差异"/></div><p class="meta">原合单与子单守恒、支付缺失或重复、退款上限、分账回退额度、孤立记录、主体错配与摘要分别核验。投影缺证保留待证，不自动改资金。</p></section><h3>渠道账单逐请求核对</h3><div class="table-scroll"><Table :columns="lineColumns" :data="detail.lines" no-data-text="此覆盖范围内暂无资金请求"/></div><Form v-if="selected&&permissions.includes('reconciliation.review')" label-position="top" class="detail-section"><h3>差异复核说明</h3><p>原请求 {{selectedRequest}}</p><FormItem label="复核依据 *"><Input v-model="reason" type="textarea" :maxlength="500" placeholder="说明核对证据与判断，不改变原金额或差异分类"/></FormItem><Button type="primary" :loading="busy" :disabled="reviewPending" @click="review">记录复核</Button><Button :disabled="busy" @click="selected=''">取消</Button></Form></template></template></Card></template>
<script>
import RecordList from './components/RecordList.vue';import OperationRecovery from './components/OperationRecovery.vue';import {s45Read,s45Commands} from '@/api/stage45';import {managerSession} from '@/libs/manager-session';import {label,date,day,money} from './presentation.cjs';
export default{components:{RecordList,OperationRecovery},data(){return{detail:null,permissions:[],accounts:[],configId:'',businessDate:null,selected:'',selectedRequest:'',reason:'',revision:0,busy:false,loading:false,error:'',ticket:0,columns:[{title:'业务日期',key:'businessDate',minWidth:140},{title:'账户',key:'account',minWidth:180},{title:'模式',minWidth:120,render:(h,{row})=>h('span',label(row.mode))},{title:'币种',key:'currency',minWidth:90},{title:'截至时点',minWidth:190,render:(h,{row})=>h('span',date(row.cutoff))},{title:'覆盖 / 差异',minWidth:260,render:(h,{row})=>h('span',Object.entries(row.coverage.counts||{}).map(([k,v])=>label(k)+' '+v).join(' · '))}]}},computed:{internalColumns(){return [{title:'原订单编号',key:'orderId',minWidth:180},{title:'核对项',key:'explanation',minWidth:280},{title:'结果',minWidth:120,render:(h,{row})=>h('span',row.severity==='PENDING'?'证据待补齐':'实际不一致')},{title:'追溯',width:140,render:(h,{row})=>h('Button',{props:{size:'small'},on:{click:()=>this.$router.push('/s45/payments/'+row.orderId)}},'核对原订单')} ]},createPending(){this.revision;return s45Commands.pending('reconciliation:create')},reviewPending(){this.revision;return s45Commands.pending('reconciliation:review:'+this.selected)},facts(){const d=this.detail;return [['渠道账户',d.account],['币种',d.currency],['业务日',d.businessDate+'（北京）'],['截至时点',date(d.cutoff)],['来源',d.sourceType==='MOCK_PROVIDER_LEDGER'?'独立 Mock 渠道账本':'待核实'],['渠道完整性',d.coverage.providerComplete?'本覆盖范围证据完整':'证据不完整'],['手续费','未提供可信账单证据'],['报告状态','已记录，复核不改变资金'] ]},lineColumns(){return [{title:'原渠道请求',key:'requestNo',minWidth:220},{title:'类型',minWidth:130,render:(h,{row})=>h('span',label(row.kind))},{title:'本地成功金额',minWidth:150,render:(h,{row})=>h('span',money(row.localCent))},{title:'渠道成功金额',minWidth:150,render:(h,{row})=>h('span',money(row.channelCent))},{title:'手续费',minWidth:130,render:(h,{row})=>h('span',money(row.feeCent))},{title:'差异',minWidth:160,render:(h,{row})=>h('span',label(row.classification))},{title:'复核说明',key:'reviewReason',minWidth:220},{title:'操作',width:110,render:(h,{row})=>this.permissions.includes('reconciliation.review')?h('Button',{props:{size:'small'},on:{click:()=>{this.selected=row.id;this.selectedRequest=row.requestNo;this.reason=''}}},'记录复核'):h('span','只读')}]}},watch:{'$route.params.id':{handler(){this.ticket++;this.detail=null;this.selected='';this.load()},immediate:true}},beforeDestroy(){this.ticket++;this.detail=null},methods:{label,async load(){const ticket=++this.ticket,owner=managerSession.snapshot();this.loading=true;this.error='';try{const c=await s45Read('/context');const id=this.$route.params.id;const v=id?await s45Read('/reconciliations/'+id):await s45Read('/reconciliation-accounts');if(ticket===this.ticket&&managerSession.sameSession(owner)){this.permissions=c.permissions;if(id)this.detail=v;else if(v)this.accounts=v.filter(row=>row.mode===c.mode)}}catch(e){if(ticket===this.ticket){this.detail=null;this.error=e.message}}finally{if(ticket===this.ticket)this.loading=false}},open(row){this.$router.push({path:'/s45/reconciliation/'+row.id,query:this.$route.query})},back(){this.$router.push({path:'/s45/reconciliation',query:this.$route.query})},create(){const selected=day(this.businessDate);if(!selected||!this.configId){this.error='请选择渠道账户与业务日。';return}this.$Modal.confirm({title:'创建本次对账报告',content:'保存当前账户、日期和截至时点的新报告；重跑会产生新报告并保留原差异。',onOk:()=>this.perform('reconciliation:create','/reconciliations',{configId:this.configId,businessDate:selected})})},review(){if(this.reason.trim().length<2){this.error='请填写至少2字的复核依据。';return}this.perform('reconciliation:review:'+this.selected,'/reconciliation-lines/'+this.selected+'/review',{reason:this.reason.trim()})},async perform(name,path,body){this.busy=true;this.error='';try{const result=await s45Commands.run(name,path,body);this.recovered(result)}catch(e){this.error=e.message}finally{this.revision++;this.busy=false}},recovered(result){this.revision++;this.selected='';this.reason='';if(result?.businessDate)this.open(result);else this.load()}}};
</script><style lang="scss">@import './stage45.scss';</style>
